mapper.select:
SELECT CP.COMPANY_ID, CP.COMPANY_NM, WC.GOVT_ID
FROM TM_COMPANY CP, TM_WORK_CP WC
WHERE CP.COMPANY_ID = WC.COMPANY_ID
  AND WC.USE_YN = 'Y'

    AND WC.WORK_CD = #{workCd}


    AND CP.COMPANY_ID = #{companyId}


    AND WC.GOVT_ID = #{govtId}

GROUP BY CP.COMPANY_ID, CP.COMPANY_NM, WC.GOVT_ID
ORDER BY CP.COMPANY_NM ASC

SELECT GROUP_ID, CODE_ID, CODE_NM, ORDER_NO FROM TM_CODE WHERE GROUP_ID IN
#{item}
AND USE_YN = 'Y' ORDER BY GROUP_ID, ORDER_NO, CODE_ID

SELECT BR.BRANCH_ID, BR.BRANCH_NM
FROM TM_BRANCH BR
WHERE BR.COMPANY_ID = #{companyId}

    AND BR.BRANCH_ID = #{branchId}

AND USE_YN = 'Y'                
ORDER BY BR.BRANCH_ID ASC

SELECT SS.SANGSA_ID, SS.SANGSA_NM
FROM TM_SANGSA SS
WHERE SS.COMPANY_ID = #{companyId}
    AND SS.BRANCH_ID = #{branchId}

    AND SS.SANGSA_ID = #{sangsaId}

AND USE_YN = 'Y'                
ORDER BY SS.BRANCH_ID, SS.SANGSA_ID ASC
